  1→import {
  2→  ChangeDetectionStrategy,
  3→  Component,
  4→  OnInit,
  5→  OnDestroy,
  6→  computed,
  7→  effect,
  8→  inject,
  9→  signal,
 10→} from "@angular/core";
 11→import { ButtonDirective } from "@aspect/ui";
 12→import { ActivatedRoute, Router } from "@angular/router";
 13→import { ClockDisplayComponent } from "../../shared/clock-display.component";
 14→import { PhaseBadgeComponent } from "../../shared/phase-badge.component";
 15→import { AmbientBackgroundComponent } from "../../shared/ambient-background.component";
 16→import { BriefingOverlayComponent } from "../../shared/briefing-overlay.component";
 17→import { CompletionOverlayComponent } from "../../shared/completion-overlay.component";
 18→import {
 19→  resolvePlayerRole,
 20→  submitRoleRecommendation,
 21→  submitDecision,
 22→} from "./player-decision-handlers";
 23→import { LogsDrawerComponent } from "../../shared/logs-drawer.component";
 24→import { StressBarComponent } from "../../shared/stress-bar.component";
 25→import { DomainService } from "../../core/domain.service";
 26→import { EngineApiService } from "../../core/engine-api.service";
 27→import { ExerciseWsService } from "../../core/exercise-ws.service";
 28→import { ExerciseStore } from "../../core/exercise.store";
 29→import { TickService } from "../../core/tick.service";
 30→import { DecisionApiService } from "../../core/decision-api.service";
 31→import { Subscription } from "rxjs";
 32→import { handlePlayerWsMessage } from "./player-ws-handler";
 33→import { RoleCardComponent } from "./role-card.component";
 34→import { SystemStatusBoardComponent } from "../../shared/system-status-board.component";
 35→import type { RoleCardSubmission } from "./role-card.component";
 36→import { buildRoleCards } from "./role-card.types";
 37→
 38→@Component({
 39→  selector: "tfc-player-view",
 40→  changeDetection: ChangeDetectionStrategy.OnPush,
 41→  providers: [ExerciseStore, TickService],
 42→  imports: [
 43→    ClockDisplayComponent,
 44→    PhaseBadgeComponent,
 45→    AmbientBackgroundComponent,
 46→    BriefingOverlayComponent,
 47→    CompletionOverlayComponent,
 48→    LogsDrawerComponent,
 49→    StressBarComponent,
 50→    ButtonDirective,
 51→    RoleCardComponent,
 52→    SystemStatusBoardComponent,
 53→  ],
 54→  templateUrl: "./player-view.html",
 55→})
 56→export class PlayerView implements OnInit, OnDestroy {
 57→  protected readonly store = inject(ExerciseStore);
 58→  protected readonly domain = inject(DomainService);
 59→  private readonly api = inject(EngineApiService);
 60→  private readonly decisionApi = inject(DecisionApiService);
 61→  protected readonly logsOpen = signal(false);
 62→  private readonly ws = inject(ExerciseWsService);
 63→  private readonly router = inject(Router);
 64→  private readonly route = inject(ActivatedRoute);
 65→  protected readonly roleLabel = signal("Advisor");
 66→  protected readonly beginningExercise = signal(false);
 67→  private readonly exerciseId = signal(1);
 68→  private readonly participantId = signal("");
 69→  private readonly tick = inject(TickService);
 70→  private snapshotLoaded = false;
 71→  private sub: Subscription | null = null;
 72→  private connSub: Subscription | null = null;
 73→
 74→  protected readonly activeDecisions = computed(() => {
 75→    const role = this.store.playerRole();
 76→    return this.store.openDecisions().filter((d) => {
 77→      if (!d.target_roles || d.target_roles.length === 0) return true;
 78→      if (
 79→        role === "all_roles" ||
 80→        role === "all_advisors" ||
 81→        role === "solo_player"
 82→      )
 83→        return true;
 84→      return d.target_roles.includes(role);
 85→    });
 86→  });
 87→
 88→  protected readonly isMultiRole = computed(() => {
 89→    const role = this.store.playerRole();
 90→    return (
 91→      role === "all_advisors" || role === "solo_player" || role === "all_roles"
 92→    );
 93→  });
 94→
 95→  protected readonly submittedRoles = signal<Set<string>>(new Set());
 96→
 97→  protected readonly currentTurnEvent = computed(() => {
 98→    const decisions = this.activeDecisions();
 99→    if (decisions.length === 0) return null;
100→    const decision = decisions[0];
101→    if (!decision.event_id) return null;
102→    return this.store.events().find((e) => e.id === decision.event_id) ?? null;
103→  });
104→
105→  protected readonly roleCards = computed(() => {
106→    const allRoles = this.store.context()?.roles ?? [];
107→    const event = this.currentTurnEvent();
108→    const decision = this.activeDecisions()[0] ?? null;
109→    const role = this.store.playerRole();
110→    const multiRole = this.isMultiRole();
111→    const playerRoleDef = allRoles.find((r) => r.id === role);
112→    const showDecisionMaker =
113→      role === "all_roles" ||
114→      role === "solo_player" ||
115→      this.store.isPracticeMode() ||
116→      playerRoleDef?.player_type === "decision_maker";
117→    // Single-role players see only their own role card
118→    const roles = multiRole ? allRoles : allRoles.filter((r) => r.id === role);
119→    return buildRoleCards(
120→      roles,
121→      event,
122→      decision,
123→      this.submittedRoles(),
124→      showDecisionMaker,
125→      allRoles,
126→    );
127→  });
128→
129→  private _lastDecisionId: string | null = null;
130→  private readonly resetSubmittedRolesEffect = effect(() => {
131→    const id = this.activeDecisions()[0]?.id ?? null;
132→    // Only reset when the decision ID actually changes (not on every WS push)
133→    if (id && id !== this._lastDecisionId) {
134→      this._lastDecisionId = id;
135→      this.submittedRoles.set(new Set());
136→    }
137→  });
138→
139→  // Turn advancement is backend-driven: closing a decision triggers the
140→  // next event in sequence automatically via engine.force_trigger_next_decision.
141→
142→  ngOnInit(): void {
143→    const params = this.route.snapshot.queryParams;
144→    const id = Number(params["exerciseId"] ?? 1);
145→    const pId = String(params["participantId"] ?? "");
146→    const role = String(params["role"] ?? "player");
147→    const gameMode = String(params["gameMode"] ?? "");
148→    this.exerciseId.set(id);
149→    this.participantId.set(pId);
150→    this.store.setParticipantId(pId);
151→    this.store.setPlayerRole(role);
152→    if (gameMode) {
153→      this.store.setGameMode(gameMode);
154→    }
155→    const practiceMode = params["practiceMode"] === "true";
156→    this.store.setPracticeMode(practiceMode);
157→    this.ws.connect(id, "player", pId || undefined);
158→    this.sub = this.ws.messages$.subscribe((msg) =>
159→      handlePlayerWsMessage(
160→        msg,
161→        this.store,
162→        () => this.onExerciseStopped(),
163→        this.ws,
164→      ),
165→    );
166→    this.loadSnapshot(id);
167→    this.decisionApi.getContext(id).subscribe({
168→      next: (ctx) =>
169→        resolvePlayerRole(ctx, role, gameMode, this.store, this.roleLabel),
170→      error: () => {},
171→    });
172→    this.decisionApi.getEngineDecisions(id).subscribe({
173→      next: (decisions) => this.store.applyDecisions(decisions),
174→      error: () => {},
175→    });
176→    this.connSub = this.ws.connected$.subscribe((connected) => {
177→      if (connected && this.snapshotLoaded) this.loadSnapshot(id);
178→    });
179→    this.tick.start(this.store);
180→  }
181→
182→  private loadSnapshot(exerciseId: number): void {
183→    this.api.snapshot(exerciseId).subscribe({
184→      next: (snap) => {
185→        this.snapshotLoaded = true;
186→        this.store.applySnapshot(snap);
187→      },
188→      error: () => this.store.setError("Failed to load snapshot"),
189→    });
190→  }
191→
192→  protected onBeginExercise(): void {
193→    this.beginningExercise.set(true);
194→    this.api.begin(this.exerciseId()).subscribe({
195→      next: (change) => {
196→        this.store.applyPhaseChange(change.phase);
197→        this.store.applyTimeUpdate(change.time);
198→        this.beginningExercise.set(false);
199→      },
200→      error: () => {
201→        this.store.setError("Failed to begin exercise");
202→        this.beginningExercise.set(false);
203→      },
204→    });
205→  }
206→
207→  protected onStop(): void {
208→    this.api.stop(this.exerciseId()).subscribe({
209→      next: () => this.onExerciseStopped(),
210→    });
211→  }
212→
213→  protected onExerciseStopped(): void {
214→    this.ws.disconnect();
215→    this.router.navigate(["/"]);
216→  }
217→
218→  ngOnDestroy(): void {
219→    this.tick.stop();
220→    this.ws.disconnect();
221→    this.sub?.unsubscribe();
222→    this.connSub?.unsubscribe();
223→  }
224→  protected onRoleCardSubmitted(submission: RoleCardSubmission): void {
225→    const decision = this.activeDecisions()[0];
226→    if (!decision) return;
227→    const role = this.store
228→      .context()
229→      ?.roles?.find((r) => r.id === submission.roleId);
230→    if (role?.player_type === "decision_maker") {
231→      submitDecision(
232→        this.decisionApi,
233→        this.store,
234→        this.exerciseId(),
235→        decision,
236→        submission,
237→      );
238→    } else {
239→      submitRoleRecommendation(
240→        this.decisionApi,
241→        this.exerciseId(),
242→        decision,
243→        this.participantId(),
244→        {
245→          roleId: submission.roleId,
246→          selectedOptions: submission.selectedOptions,
247→          freeText: submission.freeText,
248→        },
249→      );
250→    }
251→    const updated = new Set(this.submittedRoles());
252→    updated.add(submission.roleId);
253→    this.submittedRoles.set(updated);
254→  }
255→}
256→

