                <ui-badge variant="secondary">You</ui-badge>
              }
            </div>
          } @else if (currentParticipantId()) {
            <button
              uiButton
              variant="outline"
              size="sm"
              (click)="claimed.emit('game-master')"
            >
              Claim
            </button>
          } @else {
            <span class="text-sm text-muted-foreground">Open</span>
          }
        </div>
      }
    </div>
  `,
})
